"""Decode frozen 0.1s exact-precision Github subset, not interpolated; 5 fields 1e-3 precision."""
from pathlib import Path
import base64,csv
from io import StringIO
PAYLOAD=''''''
META={70:(5.72,1.95),71:(4.3,1.76),72:(4.32,1.79),73:(4.97,1.83)}
b=base64.b64decode(PAYLOAD)
nums=[];v=0;shift=0
for x in b:
 v|=(x&127)<<shift
 if x&128:shift+=7
 else:
  nums.append((v>>1) if not (v&1) else -(v>>1)-1);v=0;shift=0
assert len(nums)==4*61*5,len(nums)
output=Path(__file__).parent/'data'/'interaction_original_0p1s_70_73.csv'
with output.open('w',newline='') as o:
 w=csv.writer(o);w.writerow('track_id,frame_id,timestamp_ms,agent_type,x,y,vx,vy,psi_rad,length,width'.split(','))
 j=0
 for k,(L,W) in META.items():
  cur=[0]*5
  for t in range(61):
   for f in range(5):cur[f]+=nums[j];j+=1
   w.writerow([k,2820+t,(2820+t)*100,'car']+['%.3f'%(x/1000) for x in cur]+[L,W])
print('wrote',output,'rows',4*61)
